rules:
export const limites = {
  assunto: [4, 40],
  mensagem: [10, 200]
}

export function validar(assunto, mensagem) {
  const dados = {
    assunto: assunto.trim(),
    mensagem: mensagem.trim()
  }
  const erros = { assunto: '', mensagem: '' }
  for (const campo of Object.keys(limites)) {
    const [min, max] = limites[campo]
    const n = dados[campo].length
    if (!n) erros[campo] = `Preencha ${campo}.`
    else if (n < min || n > max)
      erros[campo] = `Use de ${min} a ${max} caracteres.`
  }
  return { dados, erros }
}

