const assunto = ref('')
const mensagem = ref('')
const erros = ref({ assunto: '', mensagem: '' })
const sucesso = ref('')

function editar(campo) {
  sucesso.value = ''
  erros.value[campo] = ''
}
function limpar() {
  assunto.value = ''
  mensagem.value = ''
  erros.value = { assunto: '', mensagem: '' }
  sucesso.value = ''
}
function enviar() {
  sucesso.value = ''
  const resultado = validar(assunto.value, mensagem.value)
  erros.value = resultado.erros
  if (erros.value.assunto || erros.value.mensagem) return
  emit('recado', resultado.dados)
  limpar()
  sucesso.value = 'Recado registrado nesta sessão.'
}

